export function count_islands(grid: string[]): number {
  const rows = grid.length;
  if (rows === 0) return 0;
  const seen: boolean[][] = grid.map((r) => new Array<boolean>(r.length).fill(false));
  let count = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < grid[r].length; c++) {
      if (grid[r][c] !== "#" || seen[r][c]) continue;
      count++;
      const stack: [number, number][] = [[r, c]];
      seen[r][c] = true;
      while (stack.length > 0) {
        const [y, x] = stack.pop()!;
        const neighbors: [number, number][] = [
          [y - 1, x], [y + 1, x], [y, x - 1], [y, x + 1],
        ];
        for (const [ny, nx] of neighbors) {
          if (
            ny >= 0 && ny < rows &&
            nx >= 0 && nx < grid[ny].length &&
            grid[ny][nx] === "#" && !seen[ny][nx]
          ) {
            seen[ny][nx] = true;
            stack.push([ny, nx]);
          }
        }
      }
    }
  }
  return count;
}
